#!/usr/bin/env python3

from __future__ import annotations

import datetime as _dt
import html
import os
import re
import shutil
import subprocess
import sys
import tempfile
import uuid
import zipfile
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any


VERSION = "0.17.0"
LOWER_VERSION = f"crowbook {VERSION}"
PLAIN_BANNER = f"CROWBOOK {VERSION}"
EMOJI_BANNER = f"\U0001f426 CROWBOOK \U0001f4da {VERSION}"

VALID_TO_VALUES = ["epub", "pdf", "html", "tex", "odt", "html.dir"]
VALID_TEMPLATE_NAMES = {
    "html.css": "templates/html.css",
    "html.css.colors": "templates/html.css.colors",
    "html.css.print": "templates/html.css.print",
    "html.dir.template": "templates/html.dir.template",
    "html.highlight.css": "templates/html.highlight.css",
    "html.highlight.js": "templates/html.highlight.js",
    "html.js": "templates/html.js",
    "html.standalone.js": "templates/html.standalone.js",
    "html.standalone.template": "templates/html.standalone.template",
    "epub.chapter.xhtml": "templates/epub.chapter.xhtml",
    "epub.css": "templates/epub.css",
    "epub.titlepage.xhtml": "templates/epub.titlepage.xhtml",
    "tex.template": "templates/tex.template",
}


class CliParseError(Exception):
    def __init__(self, message: str, exit_code: int = 2) -> None:
        super().__init__(message)
        self.message = message
        self.exit_code = exit_code


class RuntimeBookError(Exception):
    def __init__(self, message: str, suggestion: str | None = None) -> None:
        super().__init__(message)
        self.message = message
        self.suggestion = suggestion


@dataclass
class Options:
    force_emoji: bool = False
    single: bool = False
    no_fancy: bool = False
    verbose: bool = False
    autograph: bool = False
    quiet: bool = False
    create_files: list[str] | None = None
    output: str | None = None
    to: str | None = None
    set_values: list[str] = field(default_factory=list)
    list_options: bool = False
    runtime_lang: str | None = None
    print_template: str | None = None
    stats: bool = False
    help: bool = False
    version: bool = False
    book: str | None = None


@dataclass
class Block:
    kind: str
    text: str = ""
    level: int = 0
    items: list[str] = field(default_factory=list)
    info: str = ""


@dataclass
class ChapterDoc:
    source_path: Path
    raw_markdown: str
    blocks: list[Block]
    title: str


@dataclass
class BookDoc:
    source_path: Path
    base_dir: Path
    config: dict[str, Any]
    chapters: list[ChapterDoc]
    single_mode: bool


@dataclass
class RenderMessage:
    level: str
    text: str
    summary_text: str | None = None
    summary_only: bool = False


@dataclass
class RenderSuccess:
    format_name: str
    info_text: str


def repo_root() -> Path:
    here = Path(__file__).resolve().parent
    if (here / "data").exists():
        return here
    return here.parent


ROOT = repo_root()
DATA_DIR = ROOT / "data"


def read_data(relpath: str) -> str:
    return (DATA_DIR / relpath).read_text(encoding="utf-8")


def write_stderr(text: str) -> None:
    sys.stderr.write(text)
    sys.stderr.flush()


def write_stdout(text: str) -> None:
    sys.stdout.write(text)
    sys.stdout.flush()


def print_banner(opts: Options) -> None:
    if opts.quiet:
        return
    banner = EMOJI_BANNER if opts.force_emoji else PLAIN_BANNER
    write_stderr(banner + "\n")


def level_prefix(level: str, opts: Options, fancy_symbols: bool = False) -> str:
    if opts.force_emoji:
        if level == "ERROR":
            return "\U0001f4a3 ERROR"
        if level == "WARNING":
            return "\u26a0\ufe0f WARNING"
        if level == "INFO":
            return "\u2139\ufe0f INFO"
    if fancy_symbols and opts.no_fancy:
        return f"[{level if level != 'WARNING' else 'WARN'}]"
    return level


def format_relpath(path: Path) -> str:
    try:
        rel = path.resolve().relative_to(Path.cwd().resolve())
        return rel.as_posix()
    except Exception:
        try:
            return os.path.relpath(path, Path.cwd()).replace(os.sep, "/")
        except Exception:
            return str(path)


def usage_for_output(single: bool) -> str:
    if single:
        return "Usage: executable --to <to> --single --output <output> <BOOK>"
    return "Usage: executable --to <to> --output <output> <BOOK>"


def parse_args(argv: list[str]) -> Options:
    opts = Options()
    positionals: list[str] = []
    i = 0
    stop_options = False
    while i < len(argv):
        arg = argv[i]
        if stop_options:
            positionals.append(arg)
            i += 1
            continue
        if arg == "--":
            stop_options = True
            i += 1
            continue
        if arg in ("-h", "--help"):
            opts.help = True
            i += 1
            continue
        if arg in ("-V", "--version"):
            opts.version = True
            i += 1
            continue
        if arg in ("-f", "--force-emoji"):
            opts.force_emoji = True
            i += 1
            continue
        if arg in ("-s", "--single"):
            opts.single = True
            i += 1
            continue
        if arg in ("-n", "--no-fancy"):
            opts.no_fancy = True
            i += 1
            continue
        if arg in ("-v", "--verbose"):
            opts.verbose = True
            i += 1
            continue
        if arg in ("-a", "--autograph"):
            opts.autograph = True
            i += 1
            continue
        if arg in ("-q", "--quiet"):
            opts.quiet = True
            i += 1
            continue
        if arg in ("-l", "--list-options"):
            opts.list_options = True
            i += 1
            continue
        if arg in ("-S", "--stats"):
            opts.stats = True
            i += 1
            continue
        if arg in ("-c", "--create"):
            if i + 1 >= len(argv) or argv[i + 1].startswith("-"):
                raise CliParseError(
                    "error: a value is required for '--create <files>...' but none was supplied\n\n"
                    "For more information, try '--help'.\n"
                )
            values: list[str] = []
            i += 1
            while i < len(argv) and argv[i] != "--" and not argv[i].startswith("-"):
                values.append(argv[i])
                i += 1
            if not values:
                raise CliParseError(
                    "error: a value is required for '--create <files>...' but none was supplied\n\n"
                    "For more information, try '--help'.\n"
                )
            opts.create_files = values
            continue
        if arg in ("-o", "--output"):
            if i + 1 >= len(argv):
                raise CliParseError(
                    "error: a value is required for '--output <output>' but none was supplied\n\n"
                    "For more information, try '--help'.\n"
                )
            opts.output = argv[i + 1]
            i += 2
            continue
        if arg in ("-t", "--to"):
            if i + 1 >= len(argv):
                raise CliParseError(
                    "error: a value is required for '--to <to>' but none was supplied\n\n"
                    "For more information, try '--help'.\n"
                )
            value = argv[i + 1]
            if value not in VALID_TO_VALUES:
                raise CliParseError(
                    f"error: invalid value '{value}' for '--to <to>'\n"
                    "  [possible values: epub, pdf, html, tex, odt, html.dir]\n\n"
                    "For more information, try '--help'.\n"
                )
            opts.to = value
            i += 2
            continue
        if arg == "--set":
            if i + 1 >= len(argv) or argv[i + 1] == "--":
                raise CliParseError(
                    "error: a value is required for '--set <set> <set>...' but none was supplied\n\n"
                    "For more information, try '--help'.\n"
                )
            values: list[str] = []
            i += 1
            while i < len(argv) and argv[i] != "--":
                values.append(argv[i])
                i += 1
            opts.set_values.extend(values)
            continue
        if arg in ("-L", "--lang"):
            if i + 1 >= len(argv):
                raise CliParseError(
                    "error: a value is required for '--lang <lang>' but none was supplied\n\n"
                    "For more information, try '--help'.\n"
                )
            opts.runtime_lang = argv[i + 1]
            i += 2
            continue
        if arg == "--print-template":
            if i + 1 >= len(argv):
                raise CliParseError(
                    "error: a value is required for '--print-template <print-template>' but none was supplied\n\n"
                    "For more information, try '--help'.\n"
                )
            opts.print_template = argv[i + 1]
            i += 2
            continue
        if arg.startswith("-"):
            raise CliParseError(
                f"error: Found argument '{arg}' which wasn't expected, or isn't valid in this context\n\n"
                "For more information, try '--help'.\n"
            )
        positionals.append(arg)
        i += 1

    if opts.output and not opts.to:
        raise CliParseError(
            "error: the following required arguments were not provided:\n"
            "  --to <to>\n\n"
            f"{usage_for_output(opts.single)}\n\n"
            "For more information, try '--help'.\n"
        )
    if positionals:
        opts.book = positionals[0]
    return opts


def parse_simple_value(raw: str) -> Any:
    value = raw.strip()
    if value.startswith('"') and value.endswith('"') and len(value) >= 2:
        return value[1:-1]
    if value.startswith("'") and value.endswith("'") and len(value) >= 2:
        return value[1:-1]
    if value.lower() == "true":
        return True
    if value.lower() == "false":
        return False
    if re.fullmatch(r"-?\d+", value):
        try:
            return int(value)
        except ValueError:
            return value
    if value.startswith("[") and value.endswith("]"):
        inner = value[1:-1].strip()
        if not inner:
            return []
        return [parse_simple_value(part.strip()) for part in inner.split(",")]
    return value


def merge_config(base: dict[str, Any], override: dict[str, Any]) -> dict[str, Any]:
    merged = dict(base)
    merged.update(override)
    return merged


def parse_book_config(path: Path, seen: set[Path] | None = None) -> tuple[dict[str, Any], list[Path]]:
    real = path.resolve()
    if seen is None:
        seen = set()
    if real in seen:
        return {}, []
    seen.add(real)
    text = path.read_text(encoding="utf-8")
    config: dict[str, Any] = {}
    chapter_paths: list[Path] = []
    invalid_line: int | None = None
    for lineno, line in enumerate(text.splitlines(), 1):
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        if stripped.startswith("+ "):
            chapter_paths.append((path.parent / stripped[2:].strip()).resolve())
            continue
        if ":" in stripped and not stripped.startswith('"') and not stripped.startswith("'"):
            key, raw_value = stripped.split(":", 1)
            config[key.strip()] = parse_simple_value(raw_value)
            continue
        invalid_line = lineno
        break
    if invalid_line is not None:
        raise RuntimeBookError(
            f"{path}:{invalid_line}: Error parsing configuration file: \"could not parse %{{file}} as a book file.\"",
            "Maybe you meant to run crowbook with the --single argument?",
        )
    if "import" in config:
        import_path = (path.parent / str(config["import"])).resolve()
        imported_config, imported_chapters = parse_book_config(import_path, seen)
        config = merge_config(imported_config, {k: v for k, v in config.items() if k != "import"})
        chapter_paths = imported_chapters + chapter_paths
    return config, chapter_paths


def parse_frontmatter(text: str) -> tuple[dict[str, Any], str]:
    lines = text.splitlines()
    if not lines or lines[0].strip() != "---":
        return {}, text
    end = None
    for i in range(1, len(lines)):
        if lines[i].strip() == "---":
            end = i
            break
    if end is None:
        return {}, text
    meta: dict[str, Any] = {}
    for line in lines[1:end]:
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        if ":" in stripped:
            key, raw = stripped.split(":", 1)
            meta[key.strip()] = parse_simple_value(raw)
    body = "\n".join(lines[end + 1 :])
    if text.endswith("\n"):
        body += "\n"
    return meta, body


def strip_inline_markdown(text: str) -> str:
    result = text
    result = re.sub(r"!\[([^\]]*)\]\([^)]+\)", r"\1", result)
    result = re.sub(r"\[([^\]]+)\]\([^)]+\)", r"\1", result)
    result = re.sub(r"`([^`]+)`", r"\1", result)
    result = re.sub(r"\*\*([^*]+)\*\*", r"\1", result)
    result = re.sub(r"__([^_]+)__", r"\1", result)
    result = re.sub(r"(?<!\*)\*([^*]+)\*(?!\*)", r"\1", result)
    result = re.sub(r"(?<!_)_([^_]+)_(?!_)", r"\1", result)
    return result


def parse_markdown_blocks(markdown: str) -> list[Block]:
    lines = markdown.splitlines()
    blocks: list[Block] = []
    i = 0
    while i < len(lines):
        line = lines[i]
        stripped = line.strip()
        if not stripped:
            i += 1
            continue
        fence = re.match(r"^```([^`]*)$", stripped)
        if fence:
            info = fence.group(1).strip()
            i += 1
            body: list[str] = []
            while i < len(lines) and lines[i].strip() != "```":
                body.append(lines[i])
                i += 1
            if i < len(lines) and lines[i].strip() == "```":
                i += 1
            blocks.append(Block(kind="code", text="\n".join(body), info=info))
            continue
        heading = re.match(r"^(#{1,6})\s+(.*)$", stripped)
        if heading:
            blocks.append(
                Block(kind="heading", text=heading.group(2).strip(), level=len(heading.group(1)))
            )
            i += 1
            continue
        if re.match(r"^([-*])\s+\S", stripped):
            items: list[str] = []
            while i < len(lines):
                item_match = re.match(r"^\s*[-*]\s+(.*)$", lines[i])
                if not item_match:
                    break
                items.append(item_match.group(1).strip())
                i += 1
            blocks.append(Block(kind="ul", items=items))
            continue
        if re.match(r"^\d+\.\s+\S", stripped):
            items = []
            while i < len(lines):
                item_match = re.match(r"^\s*\d+\.\s+(.*)$", lines[i])
                if not item_match:
                    break
                items.append(item_match.group(1).strip())
                i += 1
            blocks.append(Block(kind="ol", items=items))
            continue
        if re.match(r"^>\s?", stripped):
            quote_lines: list[str] = []
            while i < len(lines):
                item_match = re.match(r"^\s*>\s?(.*)$", lines[i])
                if not item_match:
                    break
                quote_lines.append(item_match.group(1))
                i += 1
            blocks.append(Block(kind="blockquote", text=" ".join(s.strip() for s in quote_lines).strip()))
            continue
        if re.fullmatch(r"(\*\s*){3,}", stripped) or re.fullmatch(r"(-\s*){3,}", stripped):
            blocks.append(Block(kind="hr"))
            i += 1
            continue
        paragraph_lines = [stripped]
        i += 1
        while i < len(lines):
            next_line = lines[i].strip()
            if not next_line:
                break
            if re.match(r"^(#{1,6})\s+", next_line):
                break
            if re.match(r"^```", next_line):
                break
            if re.match(r"^([-*])\s+\S", next_line):
                break
            if re.match(r"^\d+\.\s+\S", next_line):
                break
            if re.match(r"^>\s?", next_line):
                break
            if re.fullmatch(r"(\*\s*){3,}", next_line) or re.fullmatch(r"(-\s*){3,}", next_line):
                break
            paragraph_lines.append(next_line)
            i += 1
        blocks.append(Block(kind="paragraph", text=" ".join(paragraph_lines)))
    return blocks


def load_book(opts: Options) -> BookDoc:
    if not opts.book:
        raise RuntimeBookError("You must pass the name of a book configuration file.\nFor more information try --help.")
    source_path = Path(opts.book)
    if not source_path.exists():
        raise RuntimeBookError(f"Could not find file '{opts.book}' for book")
    source_path = source_path.resolve()
    if opts.single:
        raw = source_path.read_text(encoding="utf-8")
        config, body = parse_frontmatter(raw)
        chapter = ChapterDoc(
            source_path=source_path,
            raw_markdown=body,
            blocks=parse_markdown_blocks(body),
            title=first_chapter_title(parse_markdown_blocks(body), source_path.stem),
        )
        merged = dict(config)
        merged.setdefault("lang", "en")
        apply_set_overrides(merged, opts.set_values)
        if opts.autograph:
            merged["autograph"] = prompt_autograph()
        return BookDoc(
            source_path=source_path,
            base_dir=source_path.parent,
            config=merged,
            chapters=[chapter],
            single_mode=True,
        )

    try:
        config, chapter_paths = parse_book_config(source_path)
    except RuntimeBookError:
        raise
    chapters: list[ChapterDoc] = []
    for chapter_path in chapter_paths:
        if not chapter_path.exists():
            raise RuntimeBookError(f"Could not find file '{chapter_path}' for chapter")
        raw = chapter_path.read_text(encoding="utf-8")
        blocks = parse_markdown_blocks(raw)
        chapters.append(
            ChapterDoc(
                source_path=chapter_path,
                raw_markdown=raw,
                blocks=blocks,
                title=first_chapter_title(blocks, chapter_path.stem),
            )
        )
    config.setdefault("lang", "en")
    apply_set_overrides(config, opts.set_values)
    if opts.autograph:
        config["autograph"] = prompt_autograph()
    return BookDoc(
        source_path=source_path,
        base_dir=source_path.parent,
        config=config,
        chapters=chapters,
        single_mode=False,
    )


def apply_set_overrides(config: dict[str, Any], values: list[str]) -> None:
    pairs = zip(values[0::2], values[1::2])
    for key, raw in pairs:
        config[key] = parse_simple_value(raw)


def prompt_autograph() -> str:
    write_stdout("Enter autograph:")
    line = sys.stdin.readline()
    if not line:
        return ""
    return line.rstrip("\n")


def first_chapter_title(blocks: list[Block], fallback: str) -> str:
    for block in blocks:
        if block.kind == "heading" and block.level == 1:
            return strip_inline_markdown(block.text)
    return fallback


def escape_tex(text: str) -> str:
    replacements = {
        "\\": r"\textbackslash{}",
        "{": r"\{",
        "}": r"\}",
        "$": r"\$",
        "&": r"\&",
        "%": r"\%",
        "#": r"\#",
        "_": r"\_",
        "^": r"\^{}",
        "~": r"\~{}",
    }
    return "".join(replacements.get(ch, ch) for ch in text)


def escape_tex_url(text: str) -> str:
    return text.replace("\\", "/").replace("%", r"\%").replace("#", r"\#")


def render_inline_html(text: str) -> str:
    out = html.escape(text, quote=False)
    out = re.sub(
        r"!\[([^\]]*)\]\(([^)]+)\)",
        lambda m: f'<img src = "{html.escape(m.group(2), quote=True)}" alt = "{html.escape(m.group(1), quote=True)}" />',
        out,
    )
    out = re.sub(
        r"\[([^\]]+)\]\(([^)]+)\)",
        lambda m: f'<a href = "{html.escape(m.group(2), quote=True)}">{html.escape(m.group(1), quote=False)}</a>',
        out,
    )
    out = re.sub(r"`([^`]+)`", lambda m: f"<code>{html.escape(m.group(1), quote=False)}</code>", out)
    out = re.sub(r"\*\*([^*]+)\*\*", lambda m: f"<strong>{html.escape(m.group(1), quote=False)}</strong>", out)
    out = re.sub(r"__([^_]+)__", lambda m: f"<strong>{html.escape(m.group(1), quote=False)}</strong>", out)
    out = re.sub(r"(?<!\*)\*([^*]+)\*(?!\*)", lambda m: f"<em>{html.escape(m.group(1), quote=False)}</em>", out)
    out = re.sub(r"(?<!_)_([^_]+)_(?!_)", lambda m: f"<em>{html.escape(m.group(1), quote=False)}</em>", out)
    return out


def render_inline_tex(text: str) -> str:
    placeholders: dict[str, str] = {}

    def stash(value: str) -> str:
        key = f"@@{len(placeholders)}@@"
        placeholders[key] = value
        return key

    escaped = escape_tex(text)
    escaped = re.sub(
        r"\[([^\]]+)\]\(([^)]+)\)",
        lambda m: stash(
            rf"\href{{{escape_tex_url(m.group(2))}}}{{{escape_tex(m.group(1))}}}\protect\footnote{{\url{{{escape_tex_url(m.group(2))}}}}}"
        ),
        escaped,
    )
    escaped = re.sub(r"`([^`]+)`", lambda m: stash(rf"\mdcode{{{escape_tex(m.group(1))}}}"), escaped)
    escaped = re.sub(r"\*\*([^*]+)\*\*", lambda m: stash(rf"\mdstrong{{{escape_tex(m.group(1))}}}"), escaped)
    escaped = re.sub(r"__([^_]+)__", lambda m: stash(rf"\mdstrong{{{escape_tex(m.group(1))}}}"), escaped)
    escaped = re.sub(r"(?<!\*)\*([^*]+)\*(?!\*)", lambda m: stash(rf"\emph{{{escape_tex(m.group(1))}}}"), escaped)
    escaped = re.sub(r"(?<!_)_([^_]+)_(?!_)", lambda m: stash(rf"\emph{{{escape_tex(m.group(1))}}}"), escaped)
    for key, value in placeholders.items():
        escaped = escaped.replace(key, value)
    return escaped


def block_visible_text(block: Block) -> str:
    if block.kind in {"heading", "paragraph", "blockquote"}:
        return strip_inline_markdown(block.text).replace("\n", "")
    if block.kind in {"ul", "ol"}:
        return "".join(strip_inline_markdown(item) for item in block.items)
    if block.kind == "code":
        return block.text.replace("\n", "")
    return ""


def block_word_count(block: Block) -> int:
    if block.kind == "heading":
        return 1
    if block.kind in {"ul", "ol"}:
        return 1 if block.items else 0
    text = block_visible_text(block)
    if not text.strip():
        return 0
    return len(re.findall(r"\S+", text))


def stats_text(book: BookDoc) -> str:
    rows: list[tuple[str, int, int]] = []
    total_chars = 0
    total_words = 0
    for chapter in book.chapters:
        chars = sum(len(block_visible_text(block)) for block in chapter.blocks)
        words = sum(block_word_count(block) for block in chapter.blocks)
        total_chars += chars
        total_words += words
        rows.append((chapter.source_path.name, chars, words))
    lines = ["Chapter      Chars      Words  Chars/Word", "---------"]
    for name, chars, words in rows:
        ratio = chars / words if words else 0.0
        lines.append(f"{name:<13}{chars:>10}{words:>11}{ratio:>12.2f}")
    lines.append("---------")
    total_ratio = total_chars / total_words if total_words else 0.0
    lines.append(f"TOTAL:{total_chars:>15}{total_words:>11}{total_ratio:>12.2f}")
    return "\n".join(lines) + "\n"


def data_template(name: str) -> str:
    return read_data(VALID_TEMPLATE_NAMES[name])


def render_curly_template(template: str, ctx: dict[str, Any]) -> str:
    def eval_expr(expr: str) -> bool:
        expr = expr.strip()
        if "| eq:" in expr:
            left, right = expr.split("| eq:", 1)
            left_value = str(ctx.get(left.strip(), ""))
            right_value = right.strip().strip('"').strip("'")
            return left_value == right_value
        return bool(ctx.get(expr))

    def inner(pos: int) -> tuple[str, int]:
        out: list[str] = []
        while pos < len(template):
            if template.startswith("{{", pos):
                end = template.index("}}", pos)
                key = template[pos + 2 : end].strip()
                out.append(str(ctx.get(key, "")))
                pos = end + 2
                continue
            if template.startswith("{% if", pos):
                end = template.index("%}", pos)
                expr = template[pos + 5 : end].strip()
                rendered, new_pos = inner(end + 2)
                if eval_expr(expr):
                    out.append(rendered)
                pos = new_pos
                continue
            if template.startswith("{% endif %}", pos):
                return "".join(out), pos + len("{% endif %}")
            out.append(template[pos])
            pos += 1
        return "".join(out), pos

    return inner(0)[0]


def render_angle_template(template: str, ctx: dict[str, Any]) -> str:
    def eval_expr(expr: str) -> bool:
        expr = expr.strip()
        if expr.startswith("not "):
            return not bool(ctx.get(expr[4:].strip()))
        return bool(ctx.get(expr))

    def inner(pos: int) -> tuple[str, int]:
        out: list[str] = []
        while pos < len(template):
            if template.startswith("<<", pos):
                end = template.index(">>", pos)
                key = template[pos + 2 : end].strip()
                out.append(str(ctx.get(key, "")))
                pos = end + 2
                continue
            if template.startswith("<# if", pos):
                end = template.index("#>", pos)
                expr = template[pos + 5 : end].strip()
                rendered, new_pos = inner(end + 2)
                if eval_expr(expr):
                    out.append(rendered)
                pos = new_pos
                continue
            if template.startswith("<# endif #>", pos):
                return "".join(out), pos + len("<# endif #>")
            out.append(template[pos])
            pos += 1
        return "".join(out), pos

    return inner(0)[0]


