def chapter_display_title(index: int, chapter: ChapterDoc) -> str:
    return f"{index}. {chapter.title}"


@dataclass
class HtmlRenderState:
    next_link_id: int = 1
    next_para_id: int = 1


def render_chapter_blocks_html(chapter_index: int, blocks: list[Block], state: HtmlRenderState) -> str:
    rendered: list[str] = []
    for block in blocks:
        if block.kind == "heading":
            link = state.next_link_id
            state.next_link_id += 1
            if block.level == 1:
                rendered.append(
                    f"  <h1 id = 'link-{link}'><span class = 'chapter-header'>Chapter {chapter_index}</span><br />{render_inline_html(block.text)}</h1>"
                )
            else:
                tag = f"h{min(block.level, 6)}"
                rendered.append(f'<{tag} id = "link-{link}">{render_inline_html(block.text)}</{tag}>')
            continue
        if block.kind == "paragraph":
            para = state.next_para_id
            state.next_para_id += 1
            rendered.append(f'<p id = "para-{para}">{render_inline_html(block.text)}</p>')
            continue
        if block.kind in {"ul", "ol"}:
            tag = "ul" if block.kind == "ul" else "ol"
            rendered.append(f"<{tag}>")
            for item in block.items:
                para = state.next_para_id
                state.next_para_id += 1
                rendered.append(f'<li><p id = "para-{para}">{render_inline_html(item)}</p>')
                rendered.append("</li>")
            rendered.append(f"</{tag}>")
            continue
        if block.kind == "blockquote":
            para = state.next_para_id
            state.next_para_id += 1
            rendered.append("<blockquote>")
            rendered.append(f'<p id = "para-{para}">{render_inline_html(block.text)}</p>')
            rendered.append("</blockquote>")
            continue
        if block.kind == "code":
            code = html.escape(block.text, quote=False)
            if block.info:
                rendered.append(
                    f'<pre><code class = "language-{html.escape(block.info, quote=True)}">{code}</code></pre>'
                )
            else:
                rendered.append(f"<pre><code>{code}</code></pre>")
            continue
        if block.kind == "hr":
            rendered.append('<p class = "rule">*</p>')
    return "\n".join(rendered)


def render_chapter_blocks_tex(chapter_index: int, blocks: list[Block]) -> str:
    rendered: list[str] = []
    for block in blocks:
        if block.kind == "heading":
            if block.level == 1:
                rendered.append(rf"\chapter{{{render_inline_tex(block.text)}}}")
                rendered.append(rf"\label{{chapter-{chapter_index - 1}}}")
            elif block.level == 2:
                rendered.append(rf"\section{{{render_inline_tex(block.text)}}}")
            elif block.level == 3:
                rendered.append(rf"\subsection{{{render_inline_tex(block.text)}}}")
            else:
                rendered.append(rf"\paragraph{{{render_inline_tex(block.text)}}}")
            continue
        if block.kind == "paragraph":
            rendered.append(render_inline_tex(block.text))
            rendered.append("")
            continue
        if block.kind == "blockquote":
            rendered.append(r"\begin{mdblockquote}")
            rendered.append(render_inline_tex(block.text))
            rendered.append(r"\end{mdblockquote}")
            rendered.append("")
            continue
        if block.kind in {"ul", "ol"}:
            env = "itemize" if block.kind == "ul" else "enumerate"
            rendered.append(rf"\begin{{{env}}}")
            for item in block.items:
                rendered.append(rf"\item {render_inline_tex(item)}")
                rendered.append("")
                rendered.append("")
            rendered.append(rf"\end{{{env}}}")
            continue
        if block.kind == "code":
            rendered.append(r"\begin{mdcodeblock}")
            rendered.append(block.text)
            rendered.append(r"\end{mdcodeblock}")
            rendered.append("")
            continue
        if block.kind == "hr":
            rendered.append(r"\mdrule")
            rendered.append("")
    return "\n".join(rendered)


def metadata_value(config: dict[str, Any], key: str, default: str = "") -> str:
    value = config.get(key, default)
    if value is None:
        return default
    return str(value)


def build_json_ld(config: dict[str, Any]) -> str:
    author = html.escape(metadata_value(config, "author"), quote=True)
    title = html.escape(metadata_value(config, "title"), quote=True)
    lang = html.escape(metadata_value(config, "lang", "en"), quote=True)
    return (
        "<script type = 'application/ld+json'>\n"
        "{\n"
        '    "@context": "http://schema.org/",\n'
        '    "@type": "Book",\n'
        f'    "author": "{author}",\n'
        f'    "name": "{title}",\n'
        "\n"
        "\n"
        "\n"
        "\n"
        "\n"
        f'    "inLanguage": "{lang}"\n'
        "}\n"
        "</script>"
    )


def ensure_parent(path: Path) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)


def render_html(book: BookDoc, output_path: Path) -> None:
    ensure_parent(output_path)
    state = HtmlRenderState()
    chapter_html: list[str] = []
    toc_items: list[str] = []
    for idx, chapter in enumerate(book.chapters, 1):
        rendered = render_chapter_blocks_html(idx, chapter.blocks, state)
        chapter_html.append(f'<div id = "chapter-{idx - 1}" class = "chapter">\n{rendered}\n\n</div>')
        toc_items.append(f'      <li><a href="#link-{state.next_link_id - len([b for b in chapter.blocks if b.kind == "heading"])}">{chapter_display_title(idx, chapter)}</a></li>')
    # Recompute TOC ids using a fresh pass so nested headings don't skew the chapter anchor.
    state = HtmlRenderState()
    toc_items = []
    for idx, chapter in enumerate(book.chapters, 1):
        anchor = state.next_link_id
        for block in chapter.blocks:
            if block.kind == "heading":
                state.next_link_id += 1
        toc_items.append(f'      <li><a href="#link-{anchor}">{chapter_display_title(idx, chapter)}</a></li>')
        for block in chapter.blocks:
            if block.kind != "heading":
                continue
    nav_toc = ""
    if len(book.chapters) > 1:
        nav_toc = "    <ul>\n" + "\n".join(toc_items) + "\n    </ul>"
    menu_icon_uri = read_data("menu_icon_uri.txt").strip() if (DATA_DIR / "menu_icon_uri.txt").exists() else ""
    script = render_curly_template(
        data_template("html.standalone.js"),
        {
            "common_script": data_template("html.js"),
            "one_chapter": bool(book.config.get("html.standalone.one_chapter")),
            "pages_svg": "",
            "book_svg": "",
            "loc_display_one": "Display one chapter",
            "loc_display_all": "Display all chapters",
        },
    )
    ctx = {
        "lang": html.escape(metadata_value(book.config, "lang", "en"), quote=True),
        "author_raw": html.escape(metadata_value(book.config, "author"), quote=True),
        "favicon": "",
        "title_raw": html.escape(metadata_value(book.config, "title"), quote=True),
        "style": rendered_html_css(metadata_value(book.config, "lang", "en"), metadata_value(book.config, "html.css.add")),
        "print_style": data_template("html.css.print"),
        "highlight_code": False,
        "highlight_css": "",
        "highlight_js": "",
        "script": script,
        "json_data": build_json_ld(book.config),
        "has_toc": len(book.chapters) > 1,
        "one_chapter": bool(book.config.get("html.standalone.one_chapter")),
        "loc_display_all": "Display all chapters",
        "book_svg": "",
        "title": html.escape(metadata_value(book.config, "title"), quote=False),
        "toc": nav_toc,
        "header": metadata_value(book.config, "html.header"),
        "menu_svg": menu_icon_uri,
        "loc_toc": "Table of contents",
        "author": html.escape(metadata_value(book.config, "author"), quote=False),
        "has_subtitle": bool(metadata_value(book.config, "subtitle")),
        "subtitle": html.escape(metadata_value(book.config, "subtitle"), quote=False),
        "has_autograph": bool(metadata_value(book.config, "autograph")),
        "autograph": html.escape(metadata_value(book.config, "autograph"), quote=False),
        "content": "".join(chapter_html),
        "footer": metadata_value(book.config, "html.footer"),
    }
    output_path.write_text(render_curly_template(data_template("html.standalone.template"), ctx), encoding="utf-8")


def build_epub_content_opf(book: BookDoc, chapter_files: list[str], version: int) -> str:
    identifier = f"urn:uuid:{uuid.uuid4()}"
    title = html.escape(metadata_value(book.config, "title"), quote=False)
    author = html.escape(metadata_value(book.config, "author"), quote=False)
    lang = html.escape(metadata_value(book.config, "lang", "en"), quote=False)
    chapter_manifest = "\n".join(
        f'    <item media-type="application/xhtml+xml" id="id_{name}" href="{name}"/>' for name in chapter_files
    )
    spine_items = "\n".join(f'    <itemref idref="id_{name}"/>' for name in ["title_page.xhtml"] + chapter_files)
    guide_items = [
        '    <reference type="toc" title="Table of contents" href="nav.xhtml"/>',
        '    <reference type="title-page" title="Title" href="title_page.xhtml"/>',
    ]
    if chapter_files:
        guide_items.append(
            f'    <reference type="text" title="{chapter_display_title(1, book.chapters[0])}" href="{chapter_files[0]}"/>'
        )
    if version == 3:
        modified = _dt.datetime.now(tz=_dt.timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
        return (
            '<?xml version="1.0" encoding="UTF-8"?>\n'
            '<package version="3.0" xmlns="http://www.idpf.org/2007/opf" unique-identifier="epub-id-1">\n'
            '  <metadata xmlns:dc="http://purl.org/dc/elements/1.1/"\n'
            '            xmlns:opf="http://www.idpf.org/2007/opf">\n'
            f'    <dc:identifier id="epub-id-1">{identifier}</dc:identifier>\n'
            f"    <dc:title>{title}</dc:title>\n"
            "    \n"
            "    \n"
            f'    <dc:language id="epub-creator-0">{lang}</dc:language>\n'
            "    \n"
            "    \n"
            "    \n"
            f'    <dc:creator id="epub-creator-0">{author}</dc:creator>\n'
            '    <meta refines="#epub-creator-0" property="role" scheme="marc:relators">aut</meta>\n'
            "    \n"
            "    \n"
            f'    <meta property="dcterms:modified">{modified}</meta>\n'
            "\n"
            "  </metadata>\n"
            "  <manifest>\n"
            '    <item id="ncx" href="toc.ncx" media-type="application/x-dtbncx+xml"/>\n'
            '    <item id="nav" href="nav.xhtml" media-type="application/xhtml+xml" properties="nav"/>\n'
            '    <item media-type="application/xhtml+xml" id="id_title_page.xhtml" href="title_page.xhtml"/>\n'
            f"{chapter_manifest}\n"
            '    <item media-type="text/css" id="id_stylesheet.css" href="stylesheet.css"/>\n'
            "  </manifest>\n"
            '  <spine toc="ncx" page-progression-direction="ltr">\n'
            f"{spine_items}\n"
            "  </spine>\n"
            "  <guide>\n"
            + "\n".join(guide_items)
            + "\n  </guide>\n"
            "</package>\n"
        )
    return (
        '<?xml version="1.0" encoding="UTF-8"?>\n'
        '<package version="2.0" xmlns="http://www.idpf.org/2007/opf" unique-identifier="epub-id-1">\n'
        '  <metadata xmlns:dc="http://purl.org/dc/elements/1.1/"\n'
        '            xmlns:opf="http://www.idpf.org/2007/opf">\n'
        f'    <dc:identifier id="epub-id-1">{identifier}</dc:identifier>\n'
        f"    <dc:title>{title}</dc:title>\n"
        "    \n"
        "    \n"
        f"    <dc:language>{lang}</dc:language>\n"
        "    \n"
        "    \n"
        "    \n"
        f'    <dc:creator opf:role="aut">{author}</dc:creator>\n'
        "    \n"
        "    \n"
        "\n"
        "  </metadata>\n"
        "  <manifest>\n"
        '    <item id="ncx" href="toc.ncx" media-type="application/x-dtbncx+xml"/>\n'
        '    <item id="nav" href="nav.xhtml" media-type="application/xhtml+xml"/>\n'
        '    <item media-type="application/xhtml+xml" id="id_title_page.xhtml" href="title_page.xhtml"/>\n'
        f"{chapter_manifest}\n"
        '    <item media-type="text/css" id="id_stylesheet.css" href="stylesheet.css"/>\n'
        "  </manifest>\n"
        '  <spine toc="ncx">\n'
        f"{spine_items}\n"
        "  </spine>\n"
        "  <guide>\n"
        + "\n".join(guide_items)
        + "\n  </guide>\n"
        "</package>\n"
    )


def build_epub_nav(book: BookDoc, chapter_files: list[str], version: int) -> str:
    toc_items = ['      <li><a href="title_page.xhtml">Title</a></li>']
    landmark_items = ['      <li><a epub:type="titlepage" href="title_page.xhtml">Title</a></li>']
    for idx, chapter_file in enumerate(chapter_files, 1):
        title = chapter_display_title(idx, book.chapters[idx - 1])
        toc_items.append(f'      <li><a href="{chapter_file}">{title}</a></li>')
        landmark_items.append(f'      <li><a epub:type="bodymatter" href="{chapter_file}">{title}</a></li>')
    if version == 3:
        return (
            '<?xml version="1.0" encoding="UTF-8"?>\n'
            "<!DOCTYPE html>\n"
            '<html xmlns="http://www.w3.org/1999/xhtml" xmlns:epub="http://www.idpf.org/2007/ops">\n'
            "<head>\n"
            '  <meta charset = "utf-8" />\n'
            '  <meta name="generator" content="crowbook" />\n'
            "  <title>Table of contents</title>\n"
            '  <link rel="stylesheet" type="text/css" href="stylesheet.css" />\n'
            "</head>\n"
            "<body>\n"
            '  <nav epub:type = "toc" id="toc">\n'
            '    <h1 id="toc-title">Table of contents</h1>\n'
            "    <ol>\n"
            + "\n".join(toc_items)
            + "\n    </ol>\n"
            "  </nav>\n"
            '  <nav epub:type = "landmarks">\n'
            "    <ol>\n"
            + "\n".join(landmark_items)
            + "\n    </ol>\n"
            "  </nav>\n"
            "</body>\n"
            "</html>\n"
        )
    return (
        '<?xml version="1.0" encoding="UTF-8"?>\n'
        '<!DOCTYPE html PUBLIC "-//W3C//DTD XHTML 1.1//EN" "http://www.w3.org/TR/xhtml11/DTD/xhtml11.dtd">\n'
        '<html xmlns="http://www.w3.org/1999/xhtml">\n'
        "<head>\n"
        '  <meta http-equiv="Content-Type" content="text/html; charset=utf-8" />\n'
        '  <meta http-equiv="Content-Style-Type" content="text/css" />\n'
        '  <meta name="generator" content="crowbook" />\n'
        "  <title>Table of contents</title>\n"
        '  <link rel="stylesheet" type="text/css" href="stylesheet.css" />\n'
        "</head>\n"
        "<body>\n"
        '  <div id="toc">\n'
        '    <h1 id="toc-title">Table of contents</h1>\n'
        "    <ol>\n"
        + "\n".join(toc_items)
        + "\n    </ol>\n"
        "  </div>\n"
        "</body>\n"
        "</html>\n"
    )


