def render_epub(book: BookDoc, output_path: Path) -> list[RenderMessage]:
    ensure_parent(output_path)
    version = int(book.config.get("epub.version", 2) or 2)
    css = rendered_epub_css(metadata_value(book.config, "lang", "en"), metadata_value(book.config, "epub.css.add"))
    lang = metadata_value(book.config, "lang", "en")
    state = HtmlRenderState()
    chapter_files: list[str] = []
    chapter_contents: dict[str, str] = {}
    for idx, chapter in enumerate(book.chapters, 1):
        content = render_chapter_blocks_html(idx, chapter.blocks, state)
        chapter_file = f"chapter_{idx - 1:03d}.xhtml"
        chapter_files.append(chapter_file)
        chapter_contents[chapter_file] = render_curly_template(
            data_template("epub.chapter.xhtml"),
            {
                "lang": html.escape(lang, quote=True),
                "chapter_title_raw": html.escape(chapter_display_title(idx, chapter), quote=True),
                "content": content,
            },
        )
    title_page = render_curly_template(
        data_template("epub.titlepage.xhtml"),
        {
            "lang": html.escape(lang, quote=True),
            "title_raw": html.escape(metadata_value(book.config, "title"), quote=True),
            "author": html.escape(metadata_value(book.config, "author"), quote=False),
            "title": html.escape(metadata_value(book.config, "title"), quote=False),
            "has_subtitle": bool(metadata_value(book.config, "subtitle")),
            "subtitle": html.escape(metadata_value(book.config, "subtitle"), quote=False),
            "has_autograph": bool(metadata_value(book.config, "autograph")),
            "autograph": html.escape(metadata_value(book.config, "autograph"), quote=False),
        },
    )
    with zipfile.ZipFile(output_path, "w") as zf:
        mimetype_info = zipfile.ZipInfo("mimetype")
