def render_pdf(book: BookDoc, output_path: Path) -> RenderMessage | None:
    tex_command = metadata_value(book.config, "tex.command", "xelatex")
    if shutil.which(tex_command) is None:
        return RenderMessage(level="ERROR", text=f"Error during temporary files editing: failed to run command '{tex_command}'")
    with tempfile.TemporaryDirectory() as tmpdir:
        tmp = Path(tmpdir)
        tex_path = tmp / "book.tex"
        render_tex(book, tex_path)
        try:
            subprocess.run(
                [tex_command, "-interaction=nonstopmode", tex_path.name],
                cwd=tmp,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                check=True,
            )
        except (FileNotFoundError, subprocess.CalledProcessError):
            return RenderMessage(level="ERROR", text=f"Error during temporary files editing: failed to run command '{tex_command}'")
        pdf_path = tex_path.with_suffix(".pdf")
        if not pdf_path.exists():
            return RenderMessage(level="ERROR", text=f"Error during temporary files editing: failed to run command '{tex_command}'")
        ensure_parent(output_path)
        shutil.copyfile(pdf_path, output_path)
    return None


