def output_base_dir(book: BookDoc) -> Path:
    base = metadata_value(book.config, "output.base_path")
    if not base:
        return book.base_dir
    base_path = Path(base)
    if base_path.is_absolute():
        return base_path
    return (book.base_dir / base_path).resolve()


def resolve_output_path(book: BookDoc, fmt: str, cli_output: str | None) -> Path:
    if cli_output is not None:
        path = Path(cli_output)
        if path.is_absolute():
            return path
        return (Path.cwd() / path).resolve()
    base = output_base_dir(book)
    key_map = {
        "html": "output.html",
        "html.dir": "output.html.dir",
        "epub": "output.epub",
        "tex": "output.tex",
        "pdf": "output.pdf",
        "odt": "output.odt",
    }
    if key_map.get(fmt) in book.config:
        configured = Path(str(book.config[key_map[fmt]]))
        if configured.is_absolute():
            return configured
        return (base / configured).resolve()
    stem = book.source_path.stem
    default_suffix = {
        "html": ".html",
        "epub": ".epub",
        "tex": ".tex",
        "pdf": ".pdf",
        "odt": ".odt",
        "html.dir": "",
    }[fmt]
    if fmt == "html.dir":
        return (base / stem).resolve()
    return (base / f"{stem}{default_suffix}").resolve()


def requested_formats(book: BookDoc, opts: Options) -> list[str]:
    if opts.to:
        return [opts.to]
    if "output" in book.config and isinstance(book.config["output"], list):
        return [str(item) for item in book.config["output"]]
    formats: list[str] = []
    for fmt, key in (
        ("html", "output.html"),
        ("html.dir", "output.html.dir"),
        ("epub", "output.epub"),
        ("tex", "output.tex"),
        ("pdf", "output.pdf"),
    ):
        if key in book.config:
            formats.append(fmt)
    return formats


def panic_html_dir(book: BookDoc) -> int:
    print_banner(Options(force_emoji=False, quiet=False))
    write_stderr("\n")
