        f'Some("{book.source_path}"), line: Some(6) }}, inner: InvalidOption("option \'output.html.dir\' is not present") }}\n'
    )
    write_stderr("note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n")
    return 101


def maybe_log_verbose_success(opts: Options, successes: list[RenderSuccess], messages: list[RenderMessage]) -> None:
    if opts.quiet or not opts.verbose:
        return
    timestamp = _dt.datetime.now().strftime("%H:%M:%S")
    for success in successes:
        write_stderr(f"{timestamp} [INFO] crowbook::book: {success.info_text}\n")
    for message in messages:
        if message.level == "WARNING":
            write_stderr(f"{timestamp} [WARN] crowbook::epub: {message.text}\n")


def emit_render_messages(
    opts: Options,
    requested: list[str],
    successes: list[RenderSuccess],
    messages: list[RenderMessage],
) -> None:
    if opts.quiet:
        return
    print_banner(opts)
    if opts.verbose:
        maybe_log_verbose_success(opts, successes, messages)
        return
    if opts.no_fancy:
        for message in messages:
            prefix = level_prefix(message.level, opts, fancy_symbols=True)
            write_stderr(f"{prefix} {message.text}\n")
        for success in successes:
            write_stderr(f"[INFO] {success.info_text}\n")
        return
    if not messages:
        return
    use_summary = any(msg.level == "WARNING" for msg in messages) or bool(successes) or any(
        msg.summary_only for msg in messages
    )
    if use_summary:
        write_stderr(f"{level_prefix('WARNING', opts)} Crowbook exited successfully, but the following errors occurred:\n")
        for message in messages:
            prefix = level_prefix(message.level, opts)
            line = message.summary_text or message.text
            write_stderr(f"{prefix} {line}\n")
        return
    first = messages[0]
    write_stderr(f"{level_prefix(first.level, opts)} {first.text}\n")


def render_requested_outputs(book: BookDoc, opts: Options) -> int:
    formats = requested_formats(book, opts)
    if not formats:
        if not opts.quiet:
            print_banner(opts)
        return 0

    if opts.to == "html.dir" and opts.output and "output.html.dir" not in book.config:
        return panic_html_dir(book)

    successes: list[RenderSuccess] = []
    messages: list[RenderMessage] = []
    for fmt in formats:
        if fmt == "html":
            path = resolve_output_path(book, fmt, opts.output if opts.to == fmt else None)
            render_html(book, path)
            successes.append(
                RenderSuccess(
                    format_name="html",
                    info_text=f"Succesfully generated HTML (standalone page): {format_relpath(path)}",
                )
            )
            continue
        if fmt == "epub":
            path = resolve_output_path(book, fmt, opts.output if opts.to == fmt else None)
            messages.extend(render_epub(book, path))
            successes.append(RenderSuccess(format_name="epub", info_text=f"Succesfully generated EPUB: {format_relpath(path)}"))
            continue
        if fmt == "tex":
            path = resolve_output_path(book, fmt, opts.output if opts.to == fmt else None)
            render_tex(book, path)
            successes.append(RenderSuccess(format_name="tex", info_text=f"Succesfully generated LaTeX: {format_relpath(path)}"))
            continue
        if fmt == "pdf":
            path = resolve_output_path(book, fmt, opts.output if opts.to == fmt else None)
            pdf_error = render_pdf(book, path)
            if pdf_error is not None:
                pdf_error.summary_text = f"Error rendering pdf: {pdf_error.text}"
                messages.append(pdf_error)
            else:
                successes.append(RenderSuccess(format_name="pdf", info_text=f"Succesfully generated PDF: {format_relpath(path)}"))
            continue
        if fmt == "html.dir":
            path = resolve_output_path(book, fmt, opts.output if opts.to == fmt else None)
            messages.append(render_html_dir(book, path))
            continue
        if fmt == "odt":
            messages.append(RenderMessage(level="ERROR", text="unknown format odt"))
            continue

    emit_render_messages(opts, formats, successes, messages)
    return 0


def create_output(files: list[str]) -> str:
    lines = [
        '"author: Your name"',
        '"title: Your title"',
        '"lang: en"',
        "",
        '"## Output formats"',
        "",
        '"# Uncomment and fill to generate files"',
        '"# output.html: some_file.html"',
        '"# output.epub: some_file.epub"',
        '"# output.pdf: some_file.pdf"',
        "",
        '"# Or uncomment the following to generate PDF, HTML and EPUB files based on this file\'s name"',
        '"# output: [pdf, epub, html]"',
        "",
        '"# Uncomment and fill to set cover image (for EPUB)"',
        '"# cover: some_cover.png"',
        "",
        "## List of chapters",
    ]
    for file in files:
        lines.append(f"+ {file}")
    return "\n".join(lines) + "\n"


def handle_print_template(opts: Options) -> int:
    if not opts.quiet:
        print_banner(opts)
    if opts.print_template not in VALID_TEMPLATE_NAMES:
        write_stderr(f"{level_prefix('ERROR', opts)} {opts.print_template} is not a valid template name\n")
        return 0
    write_stdout(data_template(opts.print_template))
    return 0


def run(argv: list[str]) -> int:
    try:
        opts = parse_args(argv)
    except CliParseError as exc:
        write_stderr(exc.message)
        return exc.exit_code

    if opts.help:
        write_stdout(read_data("help.txt"))
        return 0
    if opts.version:
        write_stdout(LOWER_VERSION + "\n")
        return 0
    if opts.list_options:
        if not opts.quiet:
            print_banner(opts)
        write_stdout(read_data("list_options.txt"))
        return 0
    if opts.print_template is not None:
        return handle_print_template(opts)
    if opts.create_files is not None:
        if not opts.quiet:
            print_banner(opts)
        write_stdout(create_output(opts.create_files))
        return 0

    try:
        book = load_book(opts)
    except RuntimeBookError as exc:
        if not opts.quiet:
            print_banner(opts)
        write_stderr(f"{level_prefix('ERROR', opts)} {exc.message}\n")
        if exc.suggestion:
            write_stderr(exc.suggestion + "\n")
        return 0

    if opts.stats:
        if not opts.quiet:
            print_banner(opts)
        write_stdout(stats_text(book))
        return 0

    return render_requested_outputs(book, opts)


def main() -> None:
    raise SystemExit(run(sys.argv[1:]))


if __name__ == "__main__":
    main()

