def parse_book_config(path: Path, seen: set[Path] | None = None) -> tuple[dict[str, Any], list[Path]]:
    real = path.resolve()
    if seen is None:
        seen = set()
    if real in seen:
        return {}, []
    seen.add(real)
    text = path.read_text(encoding="utf-8")
    config: dict[str, Any] = {}
    chapter_paths: list[Path] = []
    invalid_line: int | None = None
    for lineno, line in enumerate(text.splitlines(), 1):
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        if stripped.startswith("+ "):
            chapter_paths.append((path.parent / stripped[2:].strip()).resolve())
            continue
        if ":" in stripped and not stripped.startswith('"') and not stripped.startswith("'"):
            key, raw_value = stripped.split(":", 1)
            config[key.strip()] = parse_simple_value(raw_value)
            continue
        invalid_line = lineno
        break
    if invalid_line is not None:
        raise RuntimeBookError(
            f"{path}:{invalid_line}: Error parsing configuration file: \"could not parse %{{file}} as a book file.\"",
            "Maybe you meant to run crowbook with the --single argument?",
        )
    if "import" in config:
        import_path = (path.parent / str(config["import"])).resolve()
        imported_config, imported_chapters = parse_book_config(import_path, seen)
        config = merge_config(imported_config, {k: v for k, v in config.items() if k != "import"})
        chapter_paths = imported_chapters + chapter_paths
    return config, chapter_paths


def parse_frontmatter(text: str) -> tuple[dict[str, Any], str]:
    lines = text.splitlines()
    if not lines or lines[0].strip() != "---":
        return {}, text
    end = None
    for i in range(1, len(lines)):
        if lines[i].strip() == "---":
            end = i
            break
    if end is None:
        return {}, text
    meta: dict[str, Any] = {}
    for line in lines[1:end]:
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        if ":" in stripped:
            key, raw = stripped.split(":", 1)
            meta[key.strip()] = parse_simple_value(raw)
    body = "\n".join(lines[end + 1 :])
    if text.endswith("\n"):
        body += "\n"
    return meta, body


